<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TPIR Payment Report</title><style>body{font-family:Arial,sans-serif;color:#111;margin:24px}h1,h2,p{text-align:center;margin:4px}.toolbar{text-align:right;margin-bottom:18px}button{padding:9px 16px;background:#123b73;color:white;border:0;border-radius:6px}table{width:100%;border-collapse:collapse;margin-top:20px;font-size:11px}th,td{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eef2f7}.num{text-align:right}@media print{.toolbar{display:none}body{margin:8mm}@page{size:A4 landscape;margin:8mm}tr{break-inside:avoid}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button></div><h1>TMSS POLYTECHNIC INSTITUTE</h1><h2>Rangpur · TPIR</h2><p>Payment Collection Report · Records: {{count($payments)}}</p><table><thead><tr><th>#</th><th>Roll</th><th>Student</th><th>Technology</th><th>Semester</th><th>Session</th><th>Fee Title</th><th class="num">Fee Due</th><th class="num">Paid</th><th class="num">Due</th><th>Paid Date</th><th>Method</th></tr></thead><tbody>@php($dueTotal=0)@php($paidTotal=0)@foreach($payments as $i=>$p)@php($dueTotal += (float)$p->amount_due)@php($paidTotal += (float)$p->amount_paid)<tr><td>{{$i+1}}</td><td>{{$p->student?->student_id}}</td><td>{{$p->student?->name}}</td><td>{{$p->student?->technology}}</td><td>{{$p->student?->semester}}</td><td>{{$p->student?->session}}</td><td>{{$p->title}}</td><td class="num">{{number_format($p->amount_due,2)}}</td><td class="num">{{number_format($p->amount_paid,2)}}</td><td class="num">{{number_format($p->due,2)}}</td><td>{{$p->paid_date?->format('d M Y')}}</td><td>{{$p->method}}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="7">TOTAL</th><th class="num">{{number_format($dueTotal,2)}}</th><th class="num">{{number_format($paidTotal,2)}}</th><th class="num">{{number_format(max(0,$dueTotal-$paidTotal),2)}}</th><th colspan="2"></th></tr></tfoot></table><p style="margin-top:20px;font-size:11px">Printed on {{now()->format('d M Y h:i A')}}</p></body></html>
